xml.Script:
        clWhite  := 'F0F0F0';
        clCyan   := '00FFFF';
        clBlue   := '0000FF';
        clRed    := 'FF0000';
        clYellow := 'FFFF00';
        clOrange := 'FF6000';
        clGreen  := '008000';
        clPink   := 'FF69B4';

        K  := 0.7;
        C0 := K * sqrt(3) / 6;
        C1 := K * sqrt(3) / 3;
        C2 := K * 0.5;
        H  := K * sqrt(6) / 6;

        HD := H - K * 0.18;
        D  := K * 0.2;

        // Calcs angle from 2 to 3 while rotating over 1
        function Angle(x1, y1, z1, x2, y2, z2, x3, y3, z3);
        begin
          vx := y1 * z2 - y2 * z1;
          vy := z1 * x2 - z2 * x1;
          vz := x1 * y2 - x2 * y1;
          wx := y1 * z3 - y3 * z1;
          wy := z1 * x3 - z3 * x1;
          wz := x1 * y3 - x3 * y1;
          Result := ArcCos((vx*wx + vy*wy + vz*wz) / (vx^2 + vy^2 + vz^2));
        end;

        A1 := Angle( 0, C1, HD,  C2, -C0, HD,  -C2, -C0, HD);
